}

private function cmfNavDrop(flags:int) : void
{
   if((flags & 1) != 0) { this._keyboardZoomIn = false; }
   if((flags & 2) != 0) { this._keyboardZoomOut = false; }
   if((flags & 4) != 0) { this._keyboardScrollUp = false; }
   if((flags & 8) != 0) { this._keyboardScrollDown = false; }
   if((flags & 16) != 0) { this._keyboardScrollLeft = false; }
   if((flags & 32) != 0) { this._keyboardScrollRight = false; }
