// Map blur fix. mcLodContainer holds the coarse background and one ImageContainer per zoom level. Kyle's tint
// test (start F) showed the blur is the background seen through the current level: its squares are on top
// and loaded, but stop drawing after a focus change. Reloading them (rounds 2 to 4) never helped: CLIK's
// UILoader hides itself while loading and shows itself again only once its content reports a size. Start G
// confirmed the cause: after a screenshot all 4 loaded squares were hidden with their pictures intact, and
// showing them again kept the map sharp. Start H showed the other levels' loaded squares are hidden too, and
// come back blurry when their level is shown again. So CMF shows every level's hidden loaded squares again:
// on every movement tick for 3 s after each focus change (a screenshot tool or Alt+Tab), and every 250 ms
// otherwise. The first tick after a focus change also keeps the current level on top and asks the other
// levels to hide, as a level switch does. "nav layers" lines log the stack from the bottom up
// (level:squares/empty, * = current) and the current level's hidden, faded, 0-sized and blank squares,
// whenever a check shows a square again and once when the 3 s end.
private function cmfTileStack(step:String, heal:Boolean, restack:Boolean) : void
{
   var map:* = null;
   var lods:* = null;
   var current:* = null;
   var layer:* = null;
   var loader:* = null;
   var picture:* = null;
   var stack:Array = [];
   var level:String = null;
   var lod:int = 0;
   var i:int = 0;
   var j:int = 0;
   var shown:int = 0;
   var empty:int = 0;
   var hidden:int = 0;
   var flat:int = 0;
   var blank:int = 0;
   var faded:int = 0;
   var sample:String = "-";
   var raised:Boolean = false;
   var hid:int = 0;
   var healed:int = 0;
   var elsewhere:int = 0;
   try
   {
      map = this.mcHubMapZoomContainer.mcHubMapContainer;
      lods = map.mcLodContainer;
      current = lods.GetCurrentContainer();
      while(i < lods.numChildren)
      {
         layer = lods.getChildAt(i);
         level = "bg";
         lod = lods.GetMinLod();
         while(lod <= lods.GetMaxLod())
         {
            if(lods.GetContainer(lod) == layer) { level = String(lod); }
            lod++;
         }
         shown = 0;
         empty = 0;
         j = 0;
         while(j < layer.numChildren)
         {
            loader = layer.getChildAt(j);
            if(loader is HubMapTileLoader)
            {
               shown++;
               picture = loader.content;
               if(picture == null) { empty++; }
               else if(layer == current)
               {
                  if(!loader.visible) { hidden++; }
                  if(loader.alpha < 1) { faded++; }
                  if(!(loader.width > 0 && loader.height > 0)) { flat++; }
                  if("bitmapData" in picture && !(picture.bitmapData && picture.bitmapData.width > 0)) { blank++; }
                  if(sample == "-")
                  {
                     sample = Math.round(loader.width) + "x" + Math.round(loader.height) + "/" + Math.round(picture.width) + "x" + Math.round(picture.height) + ("bitmapData" in picture ? "bitmap" : "other");
                  }
                  if(heal && (!loader.visible || loader.alpha < 1))
                  {
                     loader.visible = true;
                     loader.alpha = 1;
                     healed++;
                  }
               }
               else if(heal && !loader.visible)
               {
                  // Start H: the other levels' loaded squares are hidden too; the game keeps them (same file)
                  // and never shows them again when that level comes back.
                  loader.visible = true;
                  healed++;
                  elsewhere++;
               }
            }
            j++;
         }
         if(layer != current && level != "bg" && shown > 0) { hid++; }
         stack.push(level + (layer == current ? "*" : "") + ":" + shown + "/" + empty);
         i++;
      }
      if(restack && current)
      {
         if(lods.getChildIndex(current) != lods.numChildren - 1)
         {
            lods.setChildIndex(current,lods.numChildren - 1);
            raised = true;
         }
         lod = lods.GetMinLod();
         while(lod <= lods.GetMaxLod())
         {
            if(lod != lods.GetCurrentLod()) { map.HideTiles(lod); }
            lod++;
         }
      }
      if(step != "check" || healed > 0 || raised)
      {
         this.cmfNote("nav layers step=" + step + " current=" + lods.GetCurrentLod() + " stack=" + stack.join(",") + " hidden=" + hidden + " faded=" + faded + " flat=" + flat + " blank=" + blank + " sample=" + sample + " layer=" + (current ? (current.visible ? "v" : "h") + current.alpha : "-") + (heal ? " raised=" + (raised ? "yes" : "no") + " hiding=" + hid + " shownAgain=" + healed + " elsewhere=" + elsewhere : ""));
      }
   }
   catch(error:Error)
   {
      this.cmfNote("nav layers step=" + step + " error=" + error.message);
      this._cmfTileCheckAt = 0;
   }
}

private function cmfTileHeal(now:int) : void
{
   if(this._cmfTileCheckAt != 0 && now < this._cmfTileCheckAt)
   {
      this.cmfTileStack("check",true,this._cmfTileFirst);
      this._cmfTileFirst = false;
   }
   else if(this._cmfTileCheckAt != 0)
   {
      this._cmfTileCheckAt = 0;
      this.cmfTileStack("after",false,false);
   }
   else if(now >= this._cmfTileNextAt)
   {
      this._cmfTileNextAt = now + 250;
      this.cmfTileStack("check",true,false);
   }
}

