private static function cmfFoldSpace(ch:String) : Boolean
{
   return ch == " " || ch == "\t" || ch == "\r" || ch == "\n";
}

private static function cmfFoldName(ch:String) : Boolean
{
   var code:int = 0;
   if(ch == "") { return false; }
   code = ch.charCodeAt(0);
   return (code >= 65 && code <= 90) || (code >= 97 && code <= 122) ||
      (code >= 48 && code <= 57) || ch == "_" || ch == "-" || ch == ":";
}

private static function cmfFoldToken(text:String, at:int, marker:String) : Object
