   if(end == size) { return out; }
   while(i < end && MapMenu.cmfFoldName(text.charAt(i))) { i++; }
   if(i == start) { return out; }
   tag = text.substr(start,i - start).toLowerCase();
   while(i < end)
   {
      while(i < end && MapMenu.cmfFoldSpace(text.charAt(i))) { i++; }
      if(i == end || (i == end - 1 && text.charAt(i) == "/")) { break; }
      start = i;
      while(i < end && MapMenu.cmfFoldName(text.charAt(i))) { i++; }
      if(i == start) { return out; }
      key = text.substr(start,i - start).toLowerCase();
      while(i < end && MapMenu.cmfFoldSpace(text.charAt(i))) { i++; }
      if(text.charAt(i) != "=")
      {
         if(key == marker) { return out; }
         continue;
      }
      i++;
      while(i < end && MapMenu.cmfFoldSpace(text.charAt(i))) { i++; }
      quote = text.charAt(i);
      if(quote != "'" && quote != "\"")
      {
         if(key == marker) { return out; }
         while(i < end && !MapMenu.cmfFoldSpace(text.charAt(i))) { i++; }
         continue;
      }
      i++;
      start = i;
      while(i < end && text.charAt(i) != quote) { i++; }
      if(i == end) { return out; }
      value = text.substr(start,i - start);
      i++;
      if(key == marker)
      {
         if(found || (value != "0" && value != "1")) { return out; }
         found = true;
         kind = value == "1" ? 1 : 2;
      }
   }
   if(!found) { return out; }
   if(text.charAt(end - 1) != "/")
   {
      close = end + 1;
      while(close < size && MapMenu.cmfFoldSpace(text.charAt(close))) { close++; }
      if(text.substr(close,2) != "</") { return out; }
      close += 2;
      if(text.substr(close,tag.length).toLowerCase() != tag) { return out; }
      close += tag.length;
      while(close < size && MapMenu.cmfFoldSpace(text.charAt(close))) { close++; }
      if(text.charAt(close) != ">") { return out; }
      out.end = close + 1;
   }
   out.kind = kind;
   return out;
}

private static function cmfFoldText(text:String, marker:String, open:Boolean) : Object
{
   var out:Object = {};
   var all:Array = [];
   var closed:Array = [];
   var at:int = 0;
   var cut:int = 0;
   var hidden:Boolean = false;
   var token:Object = null;
   var part:String = "";
   out.text = text;
   out.full = text;
   out.closed = text;
   out.hasFold = false;
   if(!text || !marker) { return out; }
   marker = marker.toLowerCase();
   while(at < text.length)
   {
      if(text.charAt(at) != "<") { at++; continue; }
      token = MapMenu.cmfFoldToken(text,at,marker);
      if(token.kind == 0) { at = token.end; continue; }
      part = text.substr(cut,at - cut);
      all.push(part);
      if(!hidden) { closed.push(part); }
      else if(part.length > 0) { out.hasFold = true; }
      hidden = token.kind == 1;
      at = token.end;
      cut = at;
   }
   part = text.substr(cut);
   all.push(part);
   if(!hidden) { closed.push(part); }
   else if(part.length > 0) { out.hasFold = true; }
   out.full = all.join("");
   out.closed = closed.join("");
   out.text = open ? out.full : out.closed;
   return out;
}

