{
   var box:Rectangle = null;
   if(!this._cmfPinAnchor || !this.tooltipInstance || !this.tooltipInstance.visible) { return; }
   if(MapMenu.cmfStyle("tooltip","clearAnchor",this.m_selectedPinData) != "pin")
   {
      this._cmfPinAnchor = null;
      this._cmfPinAnchorData = null;
      this._cmfClearPending = true;
      return;
   }
   box = this.mcHubMap ? this.mcHubMap.cmfSelectedDrawnBounds(this) : null;
   if(!box) { this._cmfPinAnchor = null; this._cmfClearPending = true; return; }
   if(Math.abs(box.left - this._cmfPinAnchor.left) > 3 || Math.abs(box.top - this._cmfPinAnchor.top) > 3 ||
      Math.abs(box.right - this._cmfPinAnchor.right) > 3 || Math.abs(box.bottom - this._cmfPinAnchor.bottom) > 3)
   {
      this._cmfClearPending = true;
   }
}

