// Compose with the native/wide position. Store only our delta, never the child's screen position.
protected function cmfPanelPlace(clip:DisplayObject, part:String, wideX:Number = 0, wideY:Number = 0) : void
{
   var old:Array = null;
   var dx:Number = MapMenu.cmfNum(part,"x",0) + wideX;
   var dy:Number = MapMenu.cmfNum(part,"y",0) + wideY;
   var scale:Number = MapMenu.cmfNum(part,"scale",1);
   if(!clip) { return; }
   old = this._cmfPanelPlaces ? this._cmfPanelPlaces[clip] as Array : null;
   if(old == null && dx == 0 && dy == 0 && scale == 1) { return; }
   if(this._cmfPanelPlaces == null) { this._cmfPanelPlaces = new Dictionary(true); }
   if(old == null) { old = [0,0,1]; }
   if(dx == old[0] && dy == old[1] && scale == old[2]) { return; }
   this.cmfWideMove(clip,dx - old[0],dy - old[1]);
   clip.scaleX = clip.scaleX / old[2] * scale;
   clip.scaleY = clip.scaleY / old[2] * scale;
   this._cmfPanelPlaces[clip] = [dx,dy,scale];
}

protected function cmfPanelTransforms() : void
{
   var styles:Object = MapMenu.cmfStyles;
   var active:Boolean = Boolean(styles && (styles.legend || styles.tracker || styles.preview || styles.worldButton || styles.worldHint || styles.wide)) ||
      MapMenu.cmfWideL != MapMenu.cmfSideL || MapMenu.cmfWideR - 1920 != MapMenu.cmfSideR || MapMenu.cmfWideB - 1080 != MapMenu.cmfSideD;
   var panels:Number = 1;
   var legend:Number = 1;
   var tracker:Number = 1;
   if(!active && !this._cmfPanelTransformsUsed) { return; }
   this._cmfPanelTransformsUsed = active;
   panels = MapMenu.cmfNum("wide","panels",1);
   legend = MapMenu.cmfNum("wide","panelsLegend",panels);
   tracker = MapMenu.cmfNum("wide","panelsTracker",panels);
   this.cmfPanelPlace(this.mcHubMapPinPanel,"legend",MapMenu.cmfWideL * legend - MapMenu.cmfSideL,
      (MapMenu.cmfWideB - 1080) * legend - MapMenu.cmfSideD);
   this.cmfPanelPlace(this.mcHubMapQuestTracker,"tracker",(MapMenu.cmfWideR - 1920) * tracker - MapMenu.cmfSideR);
   this.cmfPanelPlace(this.mcQTButtons,"tracker",(MapMenu.cmfWideR - 1920) * tracker - MapMenu.cmfSideR);
   this.cmfPanelPlace(this.mcWorldMapButton,"worldButton");
   this.cmfPanelPlace(this.mcGotoWorldMap,"worldHint");
   if(this.mcHubMap && this.mcHubMap.mcHubMapPreview)
   {
      this.mcHubMap.mcHubMapPreview.cmfPanelPlace();
   }
}

protected function cmfPanelText(clip:DisplayObject, part:String, prefix:String = "", depth:int = 0) : void
{
   var field:TextField = clip as TextField;
   var container:DisplayObjectContainer = clip as DisplayObjectContainer;
   var k:int = 0;
   var saved:Object = null;
   var next:Array = null;
   if(!clip || depth > 4) { return; }
   if(this._cmfPanelTexts == null) { this._cmfPanelTexts = new Dictionary(true); }
   if(field)
   {
      saved = this._cmfPanelTexts[field];
      next = MapMenu.cmfTextStyleFor(field,part,prefix,null,saved ? saved.text : null);
      if(next)
      {
         if(!saved) { saved = {"w":field.width,"h":field.height}; }
         saved.text = next;
         this._cmfPanelTexts[field] = saved;
         field.width = field.textWidth + 4;
         field.height = field.textHeight + 4;
      }
      else if(saved)
      {
         field.width = saved.w;
         field.height = saved.h;
         delete this._cmfPanelTexts[field];
      }
   }
   else if(container)
   {
      while(k < container.numChildren)
      {
         this.cmfPanelText(container.getChildAt(k),part,prefix,depth + 1);
         k++;
      }
   }
}

// A glyph's native alpha/scale is retained across native fades and provider withdrawal. No positions change.
public static function cmfGlyphLook(clip:DisplayObject, part:String, state:Array) : Array
{
   var style:Object = MapMenu.cmfPartFor(part,null);
   var glows:Array = null;
   var color:ColorTransform = null;
   var alpha:Number = 1;
   var scale:Number = 1;
   var hidden:Boolean = false;
   if(!clip || !style && !state) { return state; }
   color = clip.transform.colorTransform;
   if(!state)
   {
      state = [clip.alpha,clip.scaleX,clip.scaleY,clip.filters,clip.transform.colorTransform,
         clip.alpha,clip.scaleX,clip.scaleY,color.alphaOffset,color.alphaOffset];
   }
   else
   {
      if(clip.alpha != state[5]) { state[0] = clip.alpha; }
      if(clip.scaleX != state[6]) { state[1] = clip.scaleX; }
      if(clip.scaleY != state[7]) { state[2] = clip.scaleY; }
      if(color.alphaOffset != state[9]) { state[8] = color.alphaOffset; }
   }
   alpha = MapMenu.cmfNum(part,"alpha",1);
   scale = MapMenu.cmfNum(part,"scale",1);
   hidden = MapMenu.cmfHides(part,"all") || alpha == 0;
   clip.scaleX = state[1] * scale;
   clip.scaleY = state[2] * scale;
   glows = MapMenu.cmfGlows(style);
   clip.filters = glows != null ? glows : state[3];
   // Keep the current native transform's alpha channels while restoring only RGB.
   if(style && style.color is Number)
   {
      color.color = uint(style.color);
   }
   else
   {
      color.redMultiplier = state[4].redMultiplier;
      color.greenMultiplier = state[4].greenMultiplier;
      color.blueMultiplier = state[4].blueMultiplier;
      color.redOffset = state[4].redOffset;
      color.greenOffset = state[4].greenOffset;
      color.blueOffset = state[4].blueOffset;
   }
   // Full transparency also suppresses additive opacity; retain the native offset for withdrawal.
   color.alphaOffset = hidden ? 0 : state[8];
   clip.transform.colorTransform = color;
   // Alpha is the same transform's multiplier: compose it last, after tint/restoration.
   clip.alpha = hidden ? 0 : state[0] * alpha;
   state[5] = clip.alpha;
   state[6] = clip.scaleX;
   state[7] = clip.scaleY;
   state[9] = clip.transform.colorTransform.alphaOffset;
   return style ? state : null;
}

public static function cmfTextGlows(style:Object, prefix:String) : Array
{
   var result:Object = {};
   var suffix:String = null;
   var key:String = null;
   if(!style || prefix == "") { return MapMenu.cmfGlows(style); }
   for(key in style)
   {
      if(key.indexOf("glow") == 0) { result[key] = style[key]; }
   }
   for(key in style)
   {
      if(key.indexOf(prefix + "Glow") == 0)
      {
         suffix = "glow" + key.substr(prefix.length + 4);
         result[suffix] = style[key];
      }
   }
   return MapMenu.cmfGlows(result);
}

