   if(this.cmfWidth <= 0 && this._cmfWidthBase == null) { return; }
   // Version 13 fix round 1: the game's placements are read once and every layout starts from them.
   // A text field's width and bounds follow its current text in the game's UI, so neither is read:
   // the text width comes from the plate's centre, on which the game's fields sit, and the title keeps
   // its width and moves by half the change. Title, text, line and plate then share one centre.
