import flash.text.TextFormat;
import flash.text.TextFormatAlign;
import flash.text.TextLineMetrics;

// Fix round 1h/1i: a pack that hides the game's plate draws its frame round the text. When the title is centred and
// the text is set left or right (Map Quest Insight's formatting does so), the box is as wide as the widest line and
// stays centred where the game centres the title: the text keeps its side inside that width and moves with it, the
// title stays. With the game's plate shown, or text with one alignment, the game's layout stays. Each layout starts
// from the text's own place.
private var _cmfTextFitX:Number = NaN;
private var _cmfTextFitDx:Number = 0;

private function cmfFitText(apply:Boolean) : void
{
   var bodyAlign:String = null;
   var lo:Number = Number.POSITIVE_INFINITY;
   var hi:Number = Number.NEGATIVE_INFINITY;
   var tlo:Number = Number.POSITIVE_INFINITY;
   var thi:Number = Number.NEGATIVE_INFINITY;
   var m:TextLineMetrics = null;
   var n:int = 0;
   var wide:Number = 0;
   var middle:Number = 0;
   if(!isNaN(this._cmfTextFitX))
   {
      this.txtDescription.x = this._cmfTextFitX;
      this._cmfTextFitX = NaN;
   }
   this._cmfTextFitDx = 0;
   if(!apply || !this._data || (this.background.visible && this.background.alpha >= 0.05)) { return; }
   if(this.txtTitle.length == 0 || this.txtDescription.length == 0) { return; }
   if(this.txtTitle.getTextFormat(0,1).align != TextFormatAlign.CENTER) { return; }
   bodyAlign = this.txtDescription.getTextFormat(0,1).align;
   if(bodyAlign != TextFormatAlign.LEFT && bodyAlign != TextFormatAlign.RIGHT) { return; }
   while(n < this.txtDescription.numLines)
   {
      m = this.txtDescription.getLineMetrics(n);
      if(m && m.width > 0)
      {
         lo = Math.min(lo,m.x);
         hi = Math.max(hi,m.x + m.width);
      }
      n++;
   }
   n = 0;
   while(n < this.txtTitle.numLines)
   {
      m = this.txtTitle.getLineMetrics(n);
      if(m && m.width > 0)
      {
         tlo = Math.min(tlo,m.x);
         thi = Math.max(thi,m.x + m.width);
      }
      n++;
   }
   if(!(lo < hi) || !(tlo < thi)) { return; }
   lo += this.txtDescription.x;
   hi += this.txtDescription.x;
   tlo += this.txtTitle.x;
   thi += this.txtTitle.x;
   wide = Math.max(hi - lo,thi - tlo);
   middle = (tlo + thi) / 2;
   this._cmfTextFitX = this.txtDescription.x;
   this._cmfTextFitDx = bodyAlign == TextFormatAlign.LEFT ? middle - wide / 2 - lo : middle + wide / 2 - hi;
   this.txtDescription.x += this._cmfTextFitDx;
}

